const root = $json.body || $json;
const b = root.payload || root;
const att = (b.attendees && b.attendees[0]) || {};
const meta = b.metadata || {};
const service = (b.eventType && b.eventType.title) || b.eventTitle || b.type || 'Консультация';
const leadId = meta.lead_id || meta['lead_id'] || '';
return [{ json: {
  external_id: b.uid || b.id || '',
  attendee_name: att.name || '',
  attendee_email: att.email || '',
  service,
  lead_id: String(leadId || ''),
  start_time: b.startTime || null,
  end_time: b.endTime || null,
  meeting_url: (b.metadata && (b.metadata.videoCallUrl || b.metadata.videoCallData)) || b.location || ''
} }];
